import React from "react";
// Styles
import styled from "styled-components";
// State
import { useSelector } from "react-redux";
import { selectMode } from "../app/appSlice";
// Components
import { Alert, Button, Form, Spinner } from "react-bootstrap";
// Config
import { formspreeUrl, telegramBotToken, telegramChatId } from "../config";
// Util
import { postData, sendToTelegram } from "../utils";

// #region styled-components
const StyledForm = styled.div`
  .form-control {
    background: ${({ theme }) =>
      theme.name === "light"
        ? "rgba(var(--bs-body-color-rgb), 0.03)"
        : "var(--bs-gray-dark)"};
  }
`;
// #endregion

// #region component
const ContactForm = () => {
  const [isValidated, setIsValidated] = React.useState(false);
  const [isProcessing, setIsProcessing] = React.useState(false);
  const [success, setSuccess] = React.useState(false);
  const [danger, setDanger] = React.useState(false);
  const [dangerMessage, setDangerMessage] = React.useState(null);
  const theme = useSelector(selectMode);

  const handleSubmit = async (event) => {
    const form = event.currentTarget;
    setSuccess(false);
    setDanger(false);
    setDangerMessage(null);
    if (form.checkValidity() === false) {
      event.preventDefault();
      event.stopPropagation();
    }
    setIsValidated(true);
    const { name, email, message } = form.elements;
    const data = {
      name: name.value,
      email: email.value,
      message: message.value,
    };
    if (form.checkValidity()) {
      event.preventDefault();
      event.persist();
      setIsProcessing(true);
      try {
        // Отправка в Formspree
        let formspreeSuccess = true;
        if (formspreeUrl) {
          const formspreeResponse = await postData(formspreeUrl, data);
          if (!formspreeResponse.ok) {
            console.warn(`Formspree error: ${formspreeResponse.status}`);
            formspreeSuccess = false;
          }
        }

        // Отправка в Telegram
        let telegramSuccess = true;
        if (telegramBotToken && telegramChatId) {
          try {
            const telegramResponse = await sendToTelegram(telegramBotToken, telegramChatId, data);
            if (!telegramResponse.ok) {
              console.warn(`Telegram error: ${telegramResponse.status}`);
              telegramSuccess = false;
            }
          } catch (telegramError) {
            console.warn('Telegram send failed:', telegramError);
            telegramSuccess = false;
          }
        }

        // Если хотя бы один способ сработал, считаем успехом
        if (!formspreeSuccess && !telegramSuccess) {
          throw new Error('Ошибка отправки сообщения. Проверьте настройки Formspree и Telegram.');
        }

        setIsProcessing(false);
        setIsValidated(false);
        event.target.reset();
        setSuccess(true);
      } catch (error) {
        setIsProcessing(false);
        setIsValidated(false);
        event.target.reset();
        setDangerMessage(error.message);
        setDanger(true);
      }
    }
  };

  return (
    <StyledForm>
      <Form noValidate validated={isValidated} onSubmit={handleSubmit}>
        <Form.Group className="mx-auto mb-3 form-group" controlId="name">
          <Form.Label>ФИО</Form.Label>
          <Form.Control required type="text" placeholder="Ваше имя" />
          <Form.Control.Feedback type="invalid">
            <h5>Пожалуйста, введите корректный ФИО.</h5>
          </Form.Control.Feedback>
        </Form.Group>
        <Form.Group className="mx-auto mb-3 form-group" controlId="email">
          <Form.Label>Почта</Form.Label>
          <Form.Control
            required
            pattern="^([a-zA-Z0-9_\-\.]+)@([a-zA-Z0-9_\-\.]+)\.([a-zA-Z]{2,5})$"
            placeholder="someone@something.com"
          />
          <Form.Control.Feedback type="invalid">
            <h5>Пожалуйста, введите корректный email.</h5>
          </Form.Control.Feedback>
        </Form.Group>
        <Form.Group className="mx-auto mb-3 form-group" controlId="message">
          <Form.Label>Сообщение</Form.Label>
          <Form.Control required as="textarea" placeholder="Ваше сообщение..." />
          <Form.Control.Feedback type="invalid">
            <h5>Пожалуйста, введите корректное сообщение.</h5>
          </Form.Control.Feedback>
        </Form.Group>
        <Form.Group className="mx-auto text-center form-group">
          {formspreeUrl && (
            <Button
              size="lg"
              variant={theme === "light" ? "outline-dark" : "outline-light"}
              type="submit"
              disabled={isProcessing}
              className="my-4"
            >
              Отправить{" "}
              {isProcessing && (
                <Spinner animation="border" variant="success" size="sm" />
              )}
            </Button>
          )}
          <Alert
            show={success}
            variant="success"
            onClose={() => setSuccess(false)}
            dismissible
          >
            <Alert.Heading>Успешно! Вскоре я свяжусь с Вами.</Alert.Heading>
          </Alert>
          <Alert
            show={danger}
            variant="danger"
            onClose={() => setDanger(false)}
            dismissible
          >
            <Alert.Heading>{dangerMessage}</Alert.Heading>
          </Alert>
          <Alert show={!formspreeUrl && !telegramBotToken} variant="warning">
            <Alert.Heading>
              Настройте отправку сообщений: добавьте formspreeUrl или telegramBotToken в src/config.js
            </Alert.Heading>
          </Alert>
        </Form.Group>
      </Form>
    </StyledForm>
  );
};
// #endregion

export default ContactForm;
